select ok(not exists(select 1 from private.world_npc_memory_closure_requests where instance_id=(select instance_id from pg_temp.h1) and closed_day=3),'current open day is excluded from historical backfill');
select ok(exists(select 1 from private.world_npc_memory_closure_requests where terminal_event_id='18900000-0000-4000-8000-000000000053'),'historical terminal quest remains a durable closure request');
update private.world_npc_memory_outbox set status='completed',completed_at=clock_timestamp(),lease_until=null where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2)) and processor_kind='extract';
select private.world_npc_memory_refresh_watermark((select instance_id from pg_temp.h1),'extract','npc-memory-v1');
select private.world_npc_memory_refresh_watermark((select instance_id from pg_temp.h2),'extract','npc-memory-v1');
select is(private.world_npc_memory_backfill_closures(),4,'interrupted historical pass resumes and schedules every contiguous closure');
select is((select count(*) from private.world_npc_memory_summary_leaves l join private.world_npc_memory_summary_sets s on s.id=l.set_id where s.instance_id=(select instance_id from pg_temp.h1)),65::bigint,'historical 65-leaf closure is not clipped');
create temporary table pg_temp.history_result as select (select count(*) from private.world_npc_memory_closure_requests where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2))) requests,(select count(*) from private.world_npc_memory_summary_sets where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2))) sets,(select count(*) from private.world_npc_memory_outbox where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2)) and source_kind='memory_set') jobs;
select is(private.world_npc_memory_backfill_closures(),0,'completed historical replay is idempotent');
select is((select jsonb_build_array((select count(*) from private.world_npc_memory_closure_requests where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2))),(select count(*) from private.world_npc_memory_summary_sets where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2))),(select count(*) from private.world_npc_memory_outbox where instance_id in ((select instance_id from pg_temp.h1),(select instance_id from pg_temp.h2)) and source_kind='memory_set'))),(select jsonb_build_array(requests,sets,jobs) from pg_temp.history_result),'historical rerun leaves requests, sets, and jobs stable');
