select id,instance_id,'interaction','Scheduler failure meaningful','Durable.','npc',2,'{}',save_id,extensions.gen_random_uuid(),1,'dialogue_turn',id,1,private.world_npc_memory_source_hash('dialogue_turn',id),1,0,1,0,'attributed','npc_known',instance_id from private.world_npc_dialogue_turns where id='18900000-0000-4000-8000-000000000060';
