insert into private.world_settlements(id,save_id,day_number,source_revision,input_fingerprint,status,deadline_at,input_snapshot,input_version) select '18900000-0000-4000-8000-000000000061',save_id,1,revision,'scheduler-failure','processing',clock_timestamp(),'{}','fixture-v1' from pg_temp.r;
create or replace function private.world_npc_memory_schedule_closures(p_instance_id uuid default null) returns integer language plpgsql security definer set search_path='' as $f$
begin raise exception 'fixture scheduler failure'; end $f$;
update private.world_settlements set status='completed',completed_at=clock_timestamp() where id='18900000-0000-4000-8000-000000000061';
select is((select status from private.world_settlements where id='18900000-0000-4000-8000-000000000061'),'completed','terminal settlement persists when local scheduling raises');
